import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // 1. Ensure the caller is the owner so burn can succeed
        address owner = c.owner();
        vm.prank(owner);
        // mint tokens to owner so they have enough to burn
        c.mintToken(owner, burnAmount);
        // 2. Drive c through burn(uint256)
