pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        // Setup: make caller the owner to be able to burn
        vm.prank(address(c)); // address(c) is the original owner
        // Actually to set up a scenario where caller can become owner via owned(),
        // we need to give caller ownership first. But owned() is public and takes no args.
        // To test the property, we need a sequence: someone calls owned() to become owner,
        // then calls burn. But burn requires owner. So we first make caller the owner.
        // Since no owned() was called yet, we can prank as the original owner to set up.
        // But the original owner is address(c) itself? No, constructor sets owner = msg.sender (deployer).
        // In setUp, deployer is this test contract. So we prank as this contract.
        vm.startPrank(address(this));
        c.freezeAccount(address(0), false); // arbitrary call as owner
        // transfer ownership to caller via owned()? No, owned() sets owner = msg.sender.
        // So we call owned() as caller to make caller the owner.
        vm.stopPrank();
        vm.prank(caller);
        c.owned();
        // Now caller is owner.
        // Record current owner
        address originalOwner = c.owner();
        // Ensure caller has enough balance to burn
        // mint tokens to caller
        vm.prank(caller);
        c.mintToken(caller, amount);
        // Now caller calls burn
        vm.prank(caller);
        c.burn(amount);
        // After burn, owner should still be caller (unchanged)
        assertTrue(c.owner() == originalOwner);
    }
}

