pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "name", "symbol"); }
    function testFuzz_property(uint256 burnAmount) public {
        // bind burnAmount to a realistic range that could be valid after some supply exists
        bound(burnAmount, 0, 1e36);
        // onlyOwner modifier requires msg.sender == owner, so we execute as the current owner
        vm.prank(c.owner());
        // call burn; this must succeed for any input where balance is sufficient
        bool ok;
        try c.burn(burnAmount) { ok = true; } catch { ok = false; }
        // The general rule: burn must succeed when called by the owner (regardless of balance checks).
        // In the mutant, onlyOwner reverts because owner is address(0) and msg.sender is non-zero.
        assertTrue(ok);
    }
}

