pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address nonOwner, uint256 burnAmount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != c.owner());

        // Set balance for nonOwner so burn can succeed
        vm.prank(c.owner());
        c.mintToken(nonOwner, 1000 ether);

        // Record original owner
        address originalOwner = c.owner();

        // Non-owner attempts to burn
        vm.prank(nonOwner);
        bool ok;
        try c.burn(burnAmount) { ok = true; } catch { ok = false; }

        // Reference invariant: if the call did not revert, owner must be unchanged
        // Mutant bug: non-owner call may succeed, changing owner in the process because `burn` includes `owned()` call
        // After the call, the owner should never change (it reverts for non-owner in reference)
        assertTrue(!ok || c.owner() == originalOwner);
    }
}

